package com.yeyamo_mobile.api.recommendation_service.infrastructure.outbox;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Component;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.recommendation_service.application.port.RecommendationOutboxPort;
@Component public class JpaRecommendationOutboxAdapter implements RecommendationOutboxPort{private final RecommendationOutboxRepository repo;private final ObjectMapper mapper;public JpaRecommendationOutboxAdapter(RecommendationOutboxRepository r,ObjectMapper m){repo=r;mapper=m;}public void append(String type,String user,String correlation,Map<String,Object>payload){try{UUID id=UUID.randomUUID();Map<String,Object>event=new LinkedHashMap<>();event.put("eventId",id);event.put("eventType",type);event.put("eventVersion",1);event.put("occurredAt",Instant.now());event.put("producer","recommendation-service");event.put("aggregateType","user-recommendation");event.put("aggregateId",user);event.put("correlationId",correlation==null?id.toString():correlation);event.put("actorId",user);event.put("payload",payload);var e=new RecommendationOutboxEvent();e.id=id;e.aggregateId=user;e.eventType=type;e.occurredAt=Instant.now();e.payload=mapper.writeValueAsString(event);repo.save(e);}catch(Exception e){throw new IllegalStateException("Cannot create recommendation outbox event",e);}}}
